"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["114558"],{76437(e){e.exports=JSON.parse('{"tag":{"label":"workflow","permalink":"/sdk/tags/workflow","allTagsPath":"/sdk/tags","count":4,"items":[{"id":"guides/building-ai-agents-advanced-guide","title":"Building AI Agents \u2014 Advanced Guide","description":"Advanced patterns for AI Agent and Agentic Workflow development: instructions authoring, authentication and ACL configuration, validation rules, error recovery, deployment procedures, and anti-patterns to avoid.","permalink":"/sdk/guides/building-ai-agents-advanced-guide"},{"id":"guides/developing-apps-guide","title":"Developing ServiceNow Apps with the Now SDK","description":"Guide for ServiceNow app development using the Now SDK: project setup, fluent authoring, build/deploy workflow, and CLI reference. Start here when working on a new ServiceNow application or with the Now SDK before consulting artifact-specific guides.","permalink":"/sdk/guides/developing-apps-guide"},{"id":"api/statemodel-api","title":"StateModel","description":"Creates a State Model that defines states, transitions, and gating conditions for a table. A single StateModel() call produces the model record plus all of its state, transition, and condition records. The plugin auto-detects the model table from the target table (changerequest \u2192 chgmodel, problem \u2192 prbmodel, problemtask \u2192 prbtaskmodel, any other table \u2192 the base sttrm_model).","permalink":"/sdk/api/statemodel-api"},{"id":"api/flow/wfa-api","title":"wfa","description":"The wfa (Workflow Automation) namespace provides the core building blocks for defining Flows and Subflows. Use wfa.trigger() to start a flow, wfa.action() to execute built-in actions, and wfa.flowLogic for control flow (if/elseIf/else, forEach, doTheFollowing, doInParallel, tryCatch, appendToFlowVariables).","permalink":"/sdk/api/flow/wfa-api"}],"unlisted":false}}')}}]);